  // Postgres: UPDATE tickets SET rating_score=$2, rated_at=$3 WHERE id=$1 AND rating_score IS NULL RETURNING *
  rateTicket(id, { rating_score, rated_at }) {
    const t = tickets.get(id);
    if (!t) throw new Error(`no ticket ${id}`);
    if (t.rating_score != null) return null;
